import sys, json
try:
    data = json.loads(sys.stdin.read())
except ValueError:
    raise SystemExit(1)
if not isinstance(data, dict):
    raise SystemExit(1)
if not isinstance(data.get("labels"), list) or any(not isinstance(x,str) for x in data["labels"]) or not isinstance(data.get("values"), list) or any(type(x) is not int for x in data["values"]):
    raise SystemExit(1)
print(len(data["labels"]) == len(data["values"]))
